    private static Map<Long, String> shown(Map<Long, BigDecimal> figures) {
        Map<Long, String> shown = new LinkedHashMap<>();
        figures.forEach((id, t) -> shown.put(id, t.setScale(2).toPlainString()));
        return shown;
    }
}
